import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const group = new Group();

  // Plane size based on image aspect (512x320 ≈ 1.6)
  const width = 1.6;
  const height = 1;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously (function stays synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Entrance animation (rise‑in + weighted‑settle)
  const tl = gsap.timeline({ paused: true });
  tl.from(mesh.position, { y: 0.4, duration: 0.7, ease: 'power3.out' })
    .to(mesh.position, { y: 0, duration: 0.9, ease: 'power4.out' });
  tl.play();

  // Prepare cleanup
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    tl.kill();
    geometry.dispose();
    material.dispose();
    if (material.map && typeof material.map.dispose === 'function') {
      material.map.dispose();
    }
  };

  // Apply any cinematic primitives defined in config
  if (Array.isArray(config.cinematicPrimitives) && config.cinematicPrimitives.length) {
    const primitiveCleanups = [];
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const result = fn(group, prim.params);
        primitiveCleanups.push(result);
      }
    }
    const baseCleanup = group.userData.cleanup;
    group.userData.cleanup = () => {
      baseCleanup();
      for (const p of primitiveCleanups) {
        if (p && typeof p.cleanup === 'function') p.cleanup();
      }
    };
  }

  return group;
}
